-- findings where cve_id = "CVE-2026-1234" or text ~ "log4j" | count by asset.type
Count of findings where cve_id is "CVE-2026-1234" or the text contains "log4j", grouped by asset.type, ordered by count descending

SELECT ((SELECT a.asset_type FROM assets a WHERE a.tenant_id = $1::uuid AND a.id = findings.asset_id))::text AS c0, count(*) AS c1 FROM findings WHERE findings.tenant_id = $2 AND (findings.asset_id IN (SELECT uaa.asset_id FROM user_accessible_assets uaa WHERE uaa.user_id = $3 AND uaa.tenant_id = $4) AND NOT EXISTS (SELECT 1 FROM assets ph WHERE ph.id = findings.asset_id AND ph.tenant_id = $4 AND ph.program_only AND EXISTS (SELECT 1 FROM asset_program_links pl JOIN bounty_programs pp ON pp.tenant_id = pl.tenant_id AND pp.id = pl.program_id WHERE pl.tenant_id = ph.tenant_id AND pl.asset_id = ph.id AND pp.visibility = 'private') AND NOT EXISTS (SELECT 1 FROM asset_program_links pl JOIN bounty_programs pp ON pp.tenant_id = pl.tenant_id AND pp.id = pl.program_id WHERE pl.tenant_id = ph.tenant_id AND pl.asset_id = ph.id AND NOT (pp.visibility = 'private' AND NOT EXISTS ( SELECT 1 FROM groups pg JOIN group_members pgm ON pgm.group_id = pg.id WHERE pg.tenant_id = pp.tenant_id AND pg.id = pp.group_id AND pg.is_active AND pgm.user_id = $3))))) AND (findings.source <> 'pentest' OR findings.pentest_campaign_id IN ( SELECT pcm.campaign_id FROM pentest_campaign_members pcm WHERE pcm.user_id = $5::uuid AND pcm.tenant_id = $2 AND (pcm.role <> 'client' OR findings.status NOT IN ('draft', 'in_review')))) AND (((findings.cve_id = ANY($6::text[]) OR findings.cve_ids && $6::text[]) OR (findings.title ILIKE $7 OR findings.description ILIKE $7 OR findings.file_path ILIKE $7)) AND ((findings.status <> ALL($8::text[])) AND (findings.branch_only = $9::boolean) AND (NOT COALESCE((findings.asset_id IN (SELECT a.id FROM assets a WHERE a.tenant_id = $2 AND a.program_only)), FALSE)))) GROUP BY 1 ORDER BY c1 DESC NULLS LAST, c0 ASC NULLS LAST LIMIT 1001

